    {
      "name": "MvPolynomial.weightedHomogeneousComponent_apply",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} (n : M)\n  (φ : MvPolynomial σ R) [inst_2 : DecidableEq M],\n  (MvPolynomial.weightedHomogeneousComponent w n) φ =\n    ∑ d ∈ φ.support with (Finsupp.weight w) d = n, (MvPolynomial.monomial d) (MvPolynomial.coeff d φ)"
    },
    {
      "name": "MvPolynomial.weightedTotalDegree'_eq_bot_iff",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M]\n  [inst_2 : SemilatticeSup M] (w : σ → M) (p : MvPolynomial σ R), MvPolynomial.weightedTotalDegree' w p = ⊥ ↔ p = 0"
    },
    {
      "name": "MvPolynomial.weightedTotalDegree'",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  {M : Type u_2} →\n    [inst : CommSemiring R] →\n      {σ : Type u_3} → [AddCommMonoid M] → [SemilatticeSup M] → (σ → M) → MvPolynomial σ R → WithBot M"
    },
