      "type": "{R : Type u_1} →\n  {M : Type u_2} →\n    [inst : CommSemiring R] → {σ : Type u_3} → [AddCommMonoid M] → (σ → M) → M → MvPolynomial σ R →ₗ[R] MvPolynomial σ R"
    }
  ]
}

{
  "items": [
    {
      "name": "MvPowerSeries.exists_coeff_ne_zero_and_weightedOrder",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} (h : ↑(MvPowerSeries.weightedOrder w f).toNat = MvPowerSeries.weightedOrder w f) : ∃ d, (MvPowerSeries.coeff d) f ≠ 0 ∧ ↑((Finsupp.weight w) d) = MvPowerSeries.weightedOrder w f",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.weightedOrder_eq_nat",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ} : MvPowerSeries.weightedOrder w f = ↑n ↔ (∃ d, (MvPowerSeries.coeff d) f ≠ 0 ∧ (Finsupp.weight w) d = n) ∧ ∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    }
  ]
}

{
  "items": [
    {
      "name": "MvPowerSeries.weightedOrder",
