    },
    {
      "name": "PowerSeries.order",
      "module_name": "Mathlib.RingTheory.PowerSeries.Order",
      "kind": "definition",
      "type": "{R : Type u_1} → [Semiring R] → PowerSeries R → ℕ∞"
    },
    {
      "name": "MvPowerSeries.exists_coeff_ne_zero_and_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R},\n  ↑(MvPowerSeries.weightedOrder w f).toNat = MvPowerSeries.weightedOrder w f →\n    ∃ d, (MvPowerSeries.coeff d) f ≠ 0 ∧ ↑((Finsupp.weight w) d) = MvPowerSeries.weightedOrder w f"
    },
    {
      "name": "MvPowerSeries.exists_coeff_ne_zero_and_order",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {f : MvPowerSeries σ R},\n  ↑f.order.toNat = f.order → ∃ d, (MvPowerSeries.coeff d) f ≠ 0 ∧ ↑(Finsupp.degree d) = f.order"
    },
    {
      "name": "MvPowerSeries.weightedOrder_le",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  (MvPowerSeries.coeff d) f ≠ 0 → MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)"
    },
    {
      "name": "MvPowerSeries.weightedOrder_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {d : σ →₀ ℕ} {a : R} [inst_1 : Decidable (a = 0)],\n  MvPowerSeries.weightedOrder w ((MvPowerSeries.monomial d) a) = if a = 0 then ⊤ else ↑((Finsupp.weight w) d)"
    }
  ]
}

